function heroMarkup(){return `<section class="banner-carousel" aria-label="Banners de Acuarelas" aria-roledescription="carrusel"><h1 class="sr-only">Acuarelas Distribuidora · Librería y papelera</h1><div class="banner-stage">${heroBanners.map((b,i)=>`<div class="banner-slide banner-${b.key} ${i===0?'is-current':''}" role="group" aria-roledescription="diapositiva" aria-label="${i+1} de ${heroBanners.length}" aria-hidden="${i!==0}" ${i?'inert':''}><img src="/assets/${b.image}.jpg" alt="${b.title}" width="2048" height="747" ${i===0?'fetchpriority="high"':'loading="eager"'}><a class="banner-cta" href="${b.href}" data-link aria-label="${b.label}"><span class="sr-only">${b.label}</span></a></div>`).join('')}</div><div class="banner-controls"><div class="banner-pagination" aria-label="Elegir banner">${heroBanners.map((b,i)=>`<button type="button" data-banner-index="${i}" class="banner-dot ${i===0?'is-current':''}" aria-label="Mostrar banner ${i+1}: ${b.label}" aria-current="${i===0?'true':'false'}"></button>`).join('')}</div><button type="button" class="banner-pause" aria-label="Pausar cambio automático de banners" aria-pressed="false">Ⅱ</button></div></section>`;}
function categoryBannerMarkup(category,banners){
  if(!banners?.length)return '';
  return `<aside class="category-brand-aside"><section class="banner-carousel category-brand-carousel" aria-label="Marcas de ${esc(category)}" aria-roledescription="${banners.length>1?'carrusel':'galería'}"><div class="category-brand-heading"><span class="eyebrow">Marcas que acompañan</span><h2>El mundo ${esc(category.toLowerCase())}.</h2></div><div class="banner-stage">${banners.map((b,i)=>`<div class="banner-slide ${i===0?'is-current':''}" role="group" aria-roledescription="diapositiva" aria-label="${i+1} de ${banners.length}: ${esc(b.brand)}" aria-hidden="${i!==0}" ${i?'inert':''}><a class="category-brand-link" href="/catalogo?category=${encodeURIComponent(category)}&brand=${encodeURIComponent(b.brand)}" data-link aria-label="Explorar ${esc(b.brand)} en ${esc(category)}"><img src="${esc(b.image)}" alt="Descubrí el mundo ${esc(b.brand)}" width="2048" height="747" loading="${i===0?'eager':'lazy'}"></a></div>`).join('')}</div><div class="category-brand-footer"><a data-link class="category-brand-current" href="/catalogo?category=${encodeURIComponent(category)}&brand=${encodeURIComponent(banners[0].brand)}">${esc(banners[0].brand)} <span>↗</span></a>${banners.length>1?'<button type="button" class="banner-pause" aria-label="Pausar banners de marcas" aria-pressed="false">Ⅱ</button>':''}</div>${banners.length>1?`<div class="banner-pagination" aria-label="Elegir marca">${banners.map((b,i)=>`<button type="button" data-banner-index="${i}" class="banner-dot ${i===0?'is-current':''}" aria-label="Mostrar marca ${esc(b.brand)}" aria-current="${i===0?'true':'false'}"></button>`).join('')}</div>`:''}</section></aside>`;
}
function initCarousel(selector='.banner-carousel'){
  const carousel=$(selector);if(!carousel)return;
  const slides=[...carousel.querySelectorAll('.banner-slide')];const dots=[...carousel.querySelectorAll('.banner-dot')];const pause=carousel.querySelector('.banner-pause');let index=0,paused=false,timer,transitionTimer;
  const clearTransition=()=>{slides.forEach(slide=>slide.classList.remove('is-entering','is-leaving','slide-reverse'));};
  const show=next=>{
    const previous=index;index=(next+slides.length)%slides.length;
    slides[index].querySelector('img').loading='eager';slides[(index+1)%slides.length].querySelector('img').loading='eager';
    clearTimeout(transitionTimer);clearTransition();
    slides.forEach((slide,i)=>{slide.classList.toggle('is-current',i===index);slide.setAttribute('aria-hidden',String(i!==index));slide.inert=i!==index;});
    if(index!==previous){
      slides[previous].classList.add('is-leaving');slides[index].classList.add('is-entering');
      if(next<previous){slides[previous].classList.add('slide-reverse');slides[index].classList.add('slide-reverse');}
      transitionTimer=setTimeout(clearTransition,720);
    }
    dots.forEach((dot,i)=>{dot.classList.toggle('is-current',i===index);dot.setAttribute('aria-current',String(i===index));});carousel.dataset.current=String(index);
    const brandLink=carousel.querySelector('.category-brand-current');
    if(brandLink){const activeLink=slides[index].querySelector('a');brandLink.href=activeLink.getAttribute('href');brandLink.innerHTML=esc(slides[index].querySelector('img').alt.replace('Descubrí el mundo ',''))+' <span>↗</span>';}
  };
  const stop=()=>{clearInterval(timer);timer=null;};
  const start=()=>{stop();if(slides.length>1&&!paused&&!document.hidden&&!document.activeElement?.matches('.banner-cta,.category-brand-link,.category-brand-current'))timer=setInterval(()=>show(index+1),3000);};
  dots.forEach((dot,i)=>dot.addEventListener('click',()=>{show(i);start();}));
  pause?.addEventListener('click',()=>{paused=!paused;pause.textContent=paused?'▶':'Ⅱ';pause.setAttribute('aria-pressed',String(paused));pause.setAttribute('aria-label',paused?'Reanudar cambio automático de banners':'Pausar cambio automático de banners');start();});
  carousel.addEventListener('focusin',event=>{if(event.target.matches('.banner-cta,.category-brand-link,.category-brand-current'))stop();});carousel.addEventListener('focusout',()=>queueMicrotask(start));
  document.addEventListener('visibilitychange',start);show(0);start();
  carouselCleanup=()=>{stop();clearTimeout(transitionTimer);document.removeEventListener('visibilitychange',start);};
}
let cart=[];try{const saved=JSON.parse(localStorage.getItem('acuarelas-cart')||'[]');if(Array.isArray(saved))cart=saved.filter(x=>Number.isInteger(x.id)&&Number.isInteger(x.qty)&&x.qty>0).map(x=>({id:x.id,qty:x.qty}));}catch{}
const basketIcon='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5"><path d="m3 9 2 12h14l2-12H3Z"/><path d="m7 9 5-7 5 7M9 13v4m6-4v4"/></svg>';
const icons={truck:'<path d="M1 5h14v12H1zM15 9h4l4 5v3h-8"/><circle cx="5" cy="19" r="2"/><circle cx="19" cy="19" r="2"/>',box:'<path d="m3 7 9-5 9 5v11l-9 5-9-5V7Z"/><path d="m3 7 9 5 9-5M12 12v11M7 4l10 6"/>',shield:'<path d="m12 2 9 4v6c0 5-9 10-9 10S3 17 3 12V6l9-4Z"/><path d="m8 12 3 3 5-6"/>',heart:'<path d="M20 5c-3-3-6-1-8 1-2-2-5-4-8-1-4 4 0 9 8 15 8-6 12-11 8-15Z"/>'};
const icon = key => `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.4">${icons[key]||icons.box}</svg>`;
async function api(url,options={}){const res=await fetch(url,{...options,headers:options.body instanceof FormData?options.headers:{'Content-Type':'application/json',...options.headers}});const data=await res.json();if(!res.ok)throw new Error(data.error||'No se pudo completar la operación.');return data;}
const post=(url,data,method='POST')=>api(url,{method,body:JSON.stringify(data)});
function toast(message){clearTimeout(toastTimer);$('#toast').textContent=message;$('#toast').classList.add('visible');toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),4500);}
function saveCart(){localStorage.setItem('acuarelas-cart',JSON.stringify(cart.map(({id,qty})=>({id,qty}))));updateCount();}
function updateCount(){const count=cart.reduce((s,x)=>s+x.qty,0);$('#cart-count').textContent=count;$('#drawer-count').textContent=`(${count})`;}
async function refreshUser(){user=(await api('/api/me')).user;$('#account-link span').textContent=user?user.name.split(' ')[0]:'Mi cuenta';}
function navigate(url){history.pushState({},'',url);document.querySelectorAll('dialog[open]').forEach(d=>d.close());render();window.scrollTo(0,0);}
const heading=(title,description='',trail=title)=>`<div class="page-heading"><div class="wrap"><div class="breadcrumb"><a href="/" data-link>Inicio</a><span>/</span><span>${esc(trail)}</span></div><h1>${esc(title)}</h1>${description?`<p>${esc(description)}</p>`:''}</div></div>`;
const input=(name,label,type='text',value='',extra='')=>`<div><label for="${name}">${label}</label><input id="${name}" name="${name}" type="${type}" value="${esc(value)}" ${extra}></div>`;
function productCard(p){currentProducts.set(p.id,p);return `<article class="product-card"><button class="product-image" data-product="${p.id}" aria-label="Ver ${esc(p.name)}"><img src="${esc(p.image||'/assets/placeholder.svg')}" alt="${esc(p.name)}" loading="lazy" width="260" height="230">${p.featured?'<span class="tag">Elegido Acuarelas</span>':''}<span class="quickview" aria-hidden="true">↗</span></button><div class="product-brand">${esc(p.brand)}</div><button class="product-title" data-product="${p.id}">${esc(p.name)}</button><div class="product-bottom"><div><div class="price">${money(p.price)}</div><div class="price-caption">Precio ${p.price_type}</div></div><button class="add-button" data-add="${p.id}" aria-label="Agregar ${esc(p.name)} al carrito" ${p.stock===0?'disabled':''}>+</button></div><div class="stock ${p.stock===0?'empty':''}">${p.stock>0?'Disponible':'Sin stock'}${p.price_type==='mayorista'&&p.min_qty>1?` · Mínimo ${p.min_qty} unidades`:''}</div></article>`;}
async function home(){const data=await api('/api/products?featured=1&limit=8');return `${heroMarkup()}<div class="wrap"><div class="benefits">${[['box','Todo en un solo lugar','Escolar, comercio, agendas y papelera'],['truck','Tu pedido, a tu medida','Coordinamos la entrega con vos'],['shield','Precios para tu negocio','Acceso mayorista con autorización'],['heart','Atención de verdad','Te acompañamos en cada compra']].map(([i,t,s])=>`<div class="benefit">${icon(i)}<div><strong>${t}</strong><span>${s}</span></div></div>`).join('')}</div><section class="section"><div class="section-head"><div><h2>Un universo para cada idea.</h2><p>Encontrá eso que buscás. Y algo que no sabías que necesitabas.</p></div><a href="/catalogo" data-link class="text-link">Ver todo el catálogo <span>↗</span></a></div><div class="category-grid">${categories.map((c,i)=>`<a href="/catalogo?category=${c}" data-link class="category-card"><h3>${c}</h3><p>${['Para aprender<br>y crear sin límites.','Herramientas para<br>cada día de trabajo.','Tus planes,<br>con tu estilo.','Todo lo que<br>tu negocio necesita.'][i]}</p><img class="category-art" src="/assets/${['pencils','pens','agenda','bag'][i]}.svg" alt="" loading="lazy"><span class="circle-arrow">↗</span></a>`).join('')}</div></section><div class="brand-strip"><span>Marcas que<br>nos acompañan</span><span class="brand-word">maped</span><span class="brand-word">BIC</span><span class="brand-word">Filgo</span><span class="brand-word">Mooving</span><span class="brand-word">PIZZINI</span><span class="brand-word">Éxito</span></div><section class="section"><div class="section-head"><div><h2>Pequeñas cosas. Grandes ideas.</h2><p>Nuestros elegidos para llenar tus días de posibilidades.</p></div><a href="/catalogo" data-link class="text-link">Ver productos <span>↗</span></a></div><div class="filter-chips" id="home-chips">${['Todos',...categories].map((c,i)=>`<button class="chip ${i===0?'active':''}" data-home-category="${c}">${c}</button>`).join('')}</div><div class="product-grid" id="home-products">${data.items.map(productCard).join('')}</div></section><section class="wholesale-banner"><div><div class="eyebrow">Hagamos crecer tu negocio</div><h2>Vos ponés las ideas.<br>Nosotros, lo que necesitás.</h2><p>Si tenés una librería, un comercio o un emprendimiento, solicitá tu cuenta mayorista y accedé a precios especiales.</p></div><a class="btn light" href="/mayoristas" data-link>Quiero ser mayorista <span>↗</span></a></section><div class="brand-banners"><a href="/catalogo?brand=Maped" data-link aria-label="Ver productos Maped"><img src="/assets/maped.jpg" alt="Descubrí el mundo Maped" loading="lazy"></a><a href="/catalogo?brand=BIC" data-link aria-label="Ver productos BIC"><img src="/assets/bic.jpg" alt="Descubrí el mundo BIC" loading="lazy"></a></div></div><section class="newsletter"><div class="wrap"><div><h2>¿Buscás algo en particular?</h2><p>Te ayudamos a encontrarlo y a armar tu próximo pedido.</p></div><a class="btn outline" href="/contacto" data-link>Hablemos <span>↗</span></a></div></section>`;}
async function catalog(){const params=new URLSearchParams(location.search);params.set('limit','12');const [data,bannerGroups]=await Promise.all([api('/api/products?'+params),api('/assets/category-banners.json')]);const category=params.get('category');const brandBanners=bannerGroups[category]||[];const title=params.get('subcategory')||category||'Todo para tus ideas';return heading(title,category?'Explorá nuestra selección de '+category.toLowerCase()+'.':'Un catálogo lleno de posibilidades. Buscá, elegí y armá tu pedido.','Catálogo'+(category?' / '+category:'')+(params.get('subcategory')?' / '+params.get('subcategory'):''))+`<div class="wrap catalog-layout ${brandBanners.length?'has-brand-banners':''}"><aside class="catalog-aside"><h3>Categorías</h3>${['Todas',...categories].map(c=>`<a class="${category===c||(!category&&c==='Todas')?'selected':''}" href="/catalogo${c==='Todas'?'':'?category='+c}" data-link>${c}<span>↗</span></a>`).join('')}<label for="subcategory-filter">Subcategoría</label><select id="subcategory-filter"><option value="">Todas las subcategorías</option>${(data.subcategories||[]).map(name=>`<option value="${esc(name)}" ${params.get('subcategory')===name?'selected':''}>${esc(name)}</option>`).join('')}</select><label for="brand-filter">Marca</label><select id="brand-filter"><option value="">Todas las marcas</option>${data.brands.map(b=>`<option ${params.get('brand')===b?'selected':''}>${esc(b)}</option>`).join('')}</select><label class="check-label"><input id="stock-filter" type="checkbox" ${params.get('stock')==='1'?'checked':''}>Solo disponibles</label><p class="note">${user?.wholesale_status==='approved'?'Estás viendo tus precios mayoristas.':'Los precios publicados son minoristas.'}</p></aside>${categoryBannerMarkup(category,brandBanners)}<section class="catalog-main"><div class="catalog-toolbar"><span>${data.total} ${data.total===1?'producto':'productos'}${params.get('q')?` para “${esc(params.get('q'))}”`:''}</span><select id="sort-filter" aria-label="Ordenar productos">${[['recommended','Recomendados'],['price_asc','Menor precio'],['price_desc','Mayor precio'],['name','Nombre A–Z'],['new','Más recientes']].map(([v,t])=>`<option value="${v}" ${params.get('sort')===v?'selected':''}>${t}</option>`).join('')}</select></div>${data.items.length?`<div class="product-grid catalog-products">${data.items.map(productCard).join('')}</div>`:empty('No encontramos esos productos','Probá con otra palabra o quitá algún filtro.','/catalogo','Ver todo el catálogo')}${data.pages>1?`<div class="pagination"><button data-page="${data.page-1}" ${data.page<=1?'disabled':''}>← Anterior</button><span>Página ${data.page} de ${data.pages}</span><button data-page="${data.page+1}" ${data.page>=data.pages?'disabled':''}>Siguiente →</button></div>`:''}</section></div>`;}
const empty=(title,text,url,label)=>`<div class="empty-state"><h2>${title}</h2><p>${text}</p>${url?`<a href="${url}" data-link class="btn">${label}</a>`:''}</div>`;
function loginPanel(){return `<div class="form-panel"><div class="tabs"><button class="active" data-auth-tab="login">Iniciar sesión</button><button data-auth-tab="register">Crear cuenta</button></div><form id="auth-form" class="form-stack" data-mode="login"><div id="register-name" class="hidden">${input('name','Nombre y apellido','text','','autocomplete="name" maxlength="100"')}</div>${input('email','Email','email','','required autocomplete="email" maxlength="180"')}${input('password','Contraseña','password','','required minlength="10" maxlength="128" autocomplete="current-password"')}<p class="form-error" id="auth-error" role="alert"></p><button class="btn full" type="submit" id="auth-submit">Ingresar <span>↗</span></button><p class="note">Para solicitar precios mayoristas, primero necesitás una cuenta.</p></form></div>`;}
function wholesalePage(){const status=user?.wholesale_status;return heading('Tu negocio, con más posibilidades.','Un espacio pensado para librerías, comercios y emprendimientos.','Acceso mayorista')+`<div class="wrap form-page"><div class="form-grid"><div class="story-panel"><div class="eyebrow">Crecemos con vos</div><h2>Un buen socio<br>para tus próximas ideas.</h2><p class="lead">Accedé a precios mayoristas y armá tu pedido con el respaldo de Acuarelas.</p>${[['Creá tu cuenta','Registrate con tu email y tus datos.'],['Contanos sobre tu comercio','Completá la solicitud. Nuestro equipo revisará tu información.'],['Empezá a comprar','Cuando aprobemos tu cuenta, verás tus precios mayoristas al iniciar sesión.']].map(([t,p],i)=>`<div class="step"><span>${i+1}</span><div><h3>${t}</h3><p>${p}</p></div></div>`).join('')}</div>${!user?loginPanel():status==='approved'?`<div class="form-panel"><div class="status-banner">Tu acceso mayorista está aprobado.</div><h2>¡Ya sos parte!</h2><p>Al iniciar sesión, el catálogo y el carrito muestran tus precios mayoristas.</p><a href="/catalogo" data-link class="btn">Explorar catálogo ↗</a></div>`:`<div class="form-panel">${status==='pending'?'<div class="status-banner pending">Recibimos tu solicitud. Está pendiente de revisión por nuestro equipo.</div>':status==='rejected'?'<div class="status-banner rejected">Tu solicitud necesita una revisión. Actualizá los datos o contactanos.</div>':''}<h2>Contanos sobre tu negocio.</h2><p>Los precios mayoristas se habilitan después de nuestra aprobación.</p><form id="wholesale-form" class="form-stack">${input('company','Nombre del comercio','text',user.company,'required maxlength="150"')}${input('tax_id','CUIT / identificación fiscal','text',user.tax_id,'required maxlength="40"')}${input('phone','Teléfono de contacto','tel',user.phone,'required maxlength="40"')}${input('address','Dirección y localidad','text',user.address,'required maxlength="250"')}<label class="check-label"><input type="checkbox" required>Autorizo el uso de estos datos para evaluar mi solicitud.</label><p class="form-error" role="alert"></p><button class="btn full" type="submit">${status==='pending'?'Actualizar solicitud':'Enviar solicitud'} <span>↗</span></button></form></div>`}</div></div>`;}
async function account(){if(!user)return heading('Qué bueno verte por acá.','Ingresá a tu cuenta o creá una para seguir tus pedidos.','Mi cuenta')+`<div class="wrap form-page"><div class="form-grid"><div class="story-panel"><div class="eyebrow">Tu espacio en Acuarelas</div><h2>Ideas que se guardan.<br>Pedidos que se encuentran.</h2><p class="lead">Consultá tus compras y solicitá el acceso mayorista desde un mismo lugar.</p><img src="/assets/agenda.svg" width="280" height="280" alt="Ilustración de una agenda"></div>${loginPanel()}</div></div>`;const orders=await api('/api/orders');return heading('Hola, '+user.name.split(' ')[0]+'.','Tu cuenta, tus pedidos y tus próximas ideas.','Mi cuenta')+`<div class="wrap account-layout"><aside class="account-card"><h2>${esc(user.name)}</h2><p>${esc(user.email)}</p><p>Acceso mayorista: <strong>${({none:'Sin solicitar',pending:'En revisión',approved:'Aprobado',rejected:'Necesita revisión'})[user.wholesale_status]}</strong></p><a href="/mayoristas" data-link class="btn outline small full">Mi acceso mayorista</a>${user.role==='admin'?'<a href="/admin" data-link class="btn small full">Administrar tienda</a>':''}<button class="btn outline small full" id="logout">Cerrar sesión</button></aside><section><h2>Mis pedidos</h2>${orders.length?orders.map(o=>`<article class="order-card"><div><strong>Pedido #${String(o.id).padStart(5,'0')}</strong><span class="pill">${esc(o.status)}</span></div><div><span>${new Date(o.created_at+'Z').toLocaleDateString('es-AR')} · ${o.price_type}</span><strong>${money(o.total)}</strong></div><p>${o.items.map(l=>`${l.qty} × ${esc(l.name)}`).join(' · ')}</p></article>`).join(''):empty('Tu primera idea está por venir.','Todavía no tenés pedidos.','/catalogo','Explorar productos')}<div class="form-panel account-security"><h2>Cambiar contraseña</h2><form class="form-stack" id="password-form">${input('current','Contraseña actual','password','','required autocomplete="current-password" maxlength="128"')}${input('password','Nueva contraseña','password','','required minlength="10" maxlength="128" autocomplete="new-password"')}<p class="form-error" role="alert"></p><button class="btn" type="submit">Actualizar contraseña</button></form></div></section></div>`;}
async function hydrateCart(){const products=await Promise.all(cart.map(async l=>{try{return await api('/api/products/'+l.id);}catch{return null;}}));cart=cart.map((l,i)=>({...l,product:products[i]}));return cart;}
async function drawCart(){await hydrateCart();const total=cart.reduce((s,l)=>s+(l.product?.price||0)*l.qty,0);$('#cart-content').innerHTML=cart.length?`<div class="cart-lines">${cart.map(l=>`<div class="cart-line"><img src="${esc(l.product?.image||'/assets/placeholder.svg')}" alt=""><div><h3>${esc(l.product?.name||'Producto no disponible')}</h3><p>${money(l.product?.price||0)}</p><div class="quantity"><button data-qty="${l.id}" data-delta="-1" aria-label="Quitar una unidad">−</button><span>${l.qty}</span><button data-qty="${l.id}" data-delta="1" aria-label="Agregar una unidad">+</button></div>${!l.product||l.qty>l.product.stock?'<p class="form-error">Revisá la disponibilidad.</p>':''}</div><button class="remove" data-remove="${l.id}" aria-label="Eliminar artículo">×</button></div>`).join('')}</div><div class="cart-summary"><div class="cart-total"><span>Total</span><strong>${money(total)}</strong></div><p class="note">${user?.wholesale_status==='approved'?'Precios mayoristas de tu cuenta.':'Precios minoristas.'} La entrega se coordina con nuestro equipo.</p><a href="/checkout" data-link class="btn full">Continuar con mi pedido <span>↗</span></a><button class="btn outline full" data-close="cart-dialog">Seguir explorando</button></div>`:empty('Un carrito lleno de posibilidades.','Elegí los productos que van con tu próxima idea.','/catalogo','Explorar productos');updateCount();}
async function addProduct(id){try{const p=await api('/api/products/'+id);const line=cart.find(l=>l.id===id);const qty=line?line.qty+1:p.price_type==='mayorista'?p.min_qty:1;if(qty>p.stock)return toast('No hay stock suficiente para agregar más unidades.');if(line){line.qty=qty;line.product=p;}else cart.push({id,qty,product:p});saveCart();toast('Agregado a tu carrito');if($('#cart-dialog').open)await drawCart();}catch(e){toast(e.message);}}
async function productDetail(id){try{const p=await api('/api/products/'+id);currentProducts.set(p.id,p);$('#product-detail').innerHTML=`<div class="detail-grid"><div class="detail-art"><img src="${esc(p.image||'/assets/placeholder.svg')}" alt="${esc(p.name)}"></div><div><div class="product-brand">${esc(p.brand)} · ${esc(p.category)}${p.subcategory?' › '+esc(p.subcategory):''}</div><h2>${esc(p.name)}</h2><p>${esc(p.description)}</p><p>SKU ${esc(p.sku)}</p><div class="detail-price">${money(p.price)}</div><p>Precio ${p.price_type} · ${p.stock} unidades disponibles</p>${p.price_type==='mayorista'?`<p>Mínimo mayorista: ${p.min_qty} unidades</p>`:''}<button class="btn full" data-add="${p.id}" ${p.stock===0?'disabled':''}>Agregar al carrito <span>+</span></button></div></div>`;$('#product-dialog').showModal();}catch(e){toast(e.message);}}
async function checkout(){await hydrateCart();if(!cart.length)return heading('Tu pedido')+`<div class="wrap form-page">${empty('Primero, una buena idea.','Agregá productos al carrito para continuar.','/catalogo','Explorar catálogo')}</div>`;return heading('Dale el próximo paso a tu idea.','Completá tus datos. Nuestro equipo confirmará el pedido y coordinará el pago y la entrega.','Finalizar pedido')+`<div class="wrap checkout-layout"><div class="form-panel"><h2>Datos para tu pedido</h2><form id="checkout-form" class="form-stack"><div class="two-fields">${input('name','Nombre y apellido','text',user?.name||'','required maxlength="100" autocomplete="name"')}${input('email','Email','email',user?.email||'','required maxlength="180" autocomplete="email"')}</div>${input('phone','Teléfono','tel',user?.phone||'','required maxlength="40" autocomplete="tel"')}${input('address','Dirección y localidad / retiro a coordinar','text',user?.address||'','required maxlength="300" autocomplete="street-address"')}<div><label for="note">¿Querés contarnos algo? (opcional)</label><textarea name="note" id="note" maxlength="1000" placeholder="Horario de contacto, aclaraciones sobre la entrega…"></textarea></div><label class="check-label"><input type="checkbox" required>Acepto las <a href="/terminos" data-link>condiciones de compra</a>.</label><p class="form-error" role="alert"></p><button type="submit" class="btn full">Enviar mi pedido <span>↗</span></button><p class="note">No se realiza un cobro automático. El pedido queda pendiente de confirmación por nuestro equipo.</p></form></div><aside class="order-summary"><h2>Tu selección</h2>${cart.map(l=>`<div class="summary-line"><span>${l.qty} × ${esc(l.product?.name||'Producto no disponible')}</span><strong>${money((l.product?.price||0)*l.qty)}</strong></div>`).join('')}<div class="cart-total"><span>Total</span><strong>${money(cart.reduce((s,l)=>s+(l.product?.price||0)*l.qty,0))}</strong></div><p class="note">Precios ${user?.wholesale_status==='approved'?'mayoristas':'minoristas'}. El costo de entrega se confirma antes del pago.</p></aside></div>`;}
function contact(){return heading('Conversemos.','Una consulta, un pedido especial o una nueva idea. Estamos para ayudarte.','Contacto')+`<div class="wrap form-page"><div class="form-grid"><div class="story-panel"><div class="eyebrow">Personas del otro lado</div><h2>La atención también<br>hace la diferencia.</h2><p class="lead">Dejanos tu mensaje y tus datos de contacto. Nuestro equipo lo recibirá en el panel de atención.</p><div class="step"><span>↗</span><div><h3>¿Sos un comercio?</h3><p>Podés <a href="/mayoristas" data-link>solicitar tu acceso mayorista</a> desde la web.</p></div></div><div class="step"><span>?</span><div><h3>¿Tenés dudas sobre tu pedido?</h3><p>Incluí el número de pedido para que podamos ayudarte.</p></div></div></div><div class="form-panel"><h2>¿En qué podemos ayudarte?</h2><form id="contact-form" class="form-stack">${input('name','Tu nombre','text',user?.name||'','required maxlength="100"')}${input('email','Tu email','email',user?.email||'','required maxlength="180"')}<div><label for="message">Tu consulta</label><textarea id="message" name="message" required minlength="10" maxlength="2000"></textarea></div><p class="form-error" role="alert"></p><button class="btn full" type="submit">Enviar consulta <span>↗</span></button></form></div></div></div>`;}
function about(){return heading('El color de las buenas ideas.','Somos Acuarelas Distribuidora. Librería, papelera y todo lo que acompaña tus proyectos.','Nosotros')+`<div class="wrap"><section class="about-hero"><div><div class="eyebrow">Nuestra esencia</div><h2>Detrás de cada producto,<br>una nueva posibilidad.</h2><p>Un cuaderno que guarda un proyecto. Un lápiz que empieza un dibujo. Una agenda que organiza un sueño.</p><p>En Acuarelas reunimos artículos escolares, de comercio, agendas y papelera para acompañar a quienes aprenden, crean y emprenden.</p><a href="/catalogo" data-link class="btn">Encontrá tu próxima idea ↗</a></div><div class="about-art"><img src="/assets/pencils.svg" alt="Ilustración de lápices de colores"></div></section><section class="wholesale-banner"><div><h2>También estamos del lado de tu negocio.</h2><p>Una selección práctica y acceso mayorista para comercios autorizados.</p></div><a href="/mayoristas" data-link class="btn light">Conocé cómo funciona ↗</a></section><div class="form-page"></div></div>`;}
function help(){return heading('Respuestas para seguir creando.','Las dudas más frecuentes sobre compras y acceso mayorista.','Ayuda')+`<div class="wrap faq-list">${[['¿Puedo comprar sin ser mayorista?','Sí. El catálogo público muestra precios minoristas y podés enviar tu pedido sin crear una cuenta. Una cuenta te permite consultar tu historial.'],['¿Cómo accedo a los precios mayoristas?','Creá tu cuenta, completá la solicitud con los datos de tu comercio y esperá la revisión. Una vez aprobada, iniciá sesión para ver tus precios mayoristas.'],['¿Cómo pago mi pedido?','Esta versión recibe pedidos a confirmar. Nuestro equipo coordina contigo el medio de pago y la entrega. No se cobran tarjetas en la web.'],['¿Cómo se coordina la entrega?','Indicá tu dirección o tu preferencia de retiro en el pedido. El equipo confirmará disponibilidad, modalidad y costo de entrega antes del pago.'],['¿Hay cantidades mínimas?','Cada artículo puede tener un mínimo para compras mayoristas, visible en la ficha cuando tu cuenta está autorizada.'],['¿Qué pasa si necesito cancelar un pedido?','Contactanos indicando el número de pedido. El equipo podrá actualizar su estado y liberar el stock reservado.']].map(([q,a])=>`<details><summary>${q}</summary><p>${a}</p></details>`).join('')}<p class="note">¿Te quedó alguna duda? <a href="/contacto" data-link>Escribinos.</a></p></div>`;}
function legal(type){return heading(type==='privacidad'?'Privacidad de tus datos':'Condiciones de compra','','Información')+`<div class="wrap content-page">${type==='privacidad'?'<h2>Datos que utilizamos</h2><p>Guardamos los datos que completás al crear tu cuenta, enviar un pedido, solicitar acceso mayorista o hacer una consulta. Se utilizan para gestionar esas operaciones y contactarte.</p><h2>Cuenta y sesión</h2><p>La sesión usa una cookie necesaria para identificar tu cuenta. El carrito se guarda en tu navegador. La contraseña se almacena mediante un resumen criptográfico; el equipo no necesita conocerla.</p><h2>Consultas sobre tus datos</h2><p>Podés solicitar la revisión o eliminación de tus datos desde el formulario de contacto. Los datos de pedidos pueden conservarse cuando resulte necesario para su gestión.</p>':'<h2>Pedidos a confirmar</h2><p>Al enviar tu selección generás un pedido pendiente. Acuarelas debe confirmar disponibilidad, condiciones de pago y entrega antes de completarlo. No se realiza un cobro automático en este sitio.</p><h2>Precios y acceso mayorista</h2><p>Los precios se expresan en pesos argentinos. Los precios públicos son minoristas. Los precios mayoristas requieren una cuenta autorizada y pueden tener cantidades mínimas por artículo.</p><h2>Entregas y cancelaciones</h2><p>La entrega, su costo y los plazos se coordinan antes del pago. Para solicitar cambios o cancelaciones, contactanos indicando el número de pedido.</p>'}<a href="/contacto" data-link class="btn outline">Hacer una consulta ↗</a></div>`;}
async function admin(){if(user?.role!=='admin')return heading('Administración','Ingresá con una cuenta administradora para gestionar Acuarelas.')+`<div class="wrap form-page">${user?empty('Acceso exclusivo del equipo','Tu cuenta no tiene permisos de administración.','/cuenta','Ir a mi cuenta'):`<div class="form-grid"><div class="story-panel"><h2>Todo bajo control.</h2><p class="lead">Gestioná productos, precios, pedidos y solicitudes mayoristas.</p><p class="note">El acceso inicial de esta instalación local se encuentra en el archivo data/ACCESO-LOCAL.txt.</p></div>${loginPanel()}</div>`}</div>`;const [stats,config]=await Promise.all([api('/api/admin/overview'),api('/api/admin/config')]);adminConfig=config;return heading('El escritorio de Acuarelas.','Productos, comercios y pedidos. Todo en un lugar.','Administración')+`<div class="wrap admin-wrap"><div class="stats">${[['Productos activos',stats.products],['Solicitudes pendientes',stats.pending],['Pedidos recibidos',stats.orders],['Artículos con stock bajo',stats.lowStock]].map(([label,n])=>`<div class="stat"><span>${label}</span><strong>${n}</strong></div>`).join('')}</div><div class="admin-tabs">${[['productos','Productos'],['excel','Importar / exportar Excel'],['imagenes','Imágenes'],['solicitudes','Acceso mayorista'],['pedidos','Pedidos'],['mensajes','Consultas']].map(([id,label])=>`<button data-admin-tab="${id}" class="${adminTab===id?'active':''}">${label}</button>`).join('')}</div><section id="admin-content">${await adminContent()}</section></div>`;}
async function adminContent(){if(adminTab==='productos'){const data=await api(`/api/admin/products?page=${adminPage}&q=${encodeURIComponent(adminQ)}`);return `<div class="admin-actions"><input id="admin-search" placeholder="Buscar por nombre o SKU" aria-label="Buscar productos en administración" value="${esc(adminQ)}"><div><button class="btn" id="new-product">Nuevo artículo <span>+</span></button><a class="btn outline" href="/api/admin/excel">Exportar Excel ↓</a></div></div><div id="product-editor"></div><div class="table-scroll"><table class="data-table"><thead><tr><th>SKU / Producto</th><th>Categoría</th><th>Minorista</th><th>Mayorista</th><th>Stock</th><th>Estado</th><th>Acciones</th></tr></thead><tbody>${data.items.map(p=>{currentProducts.set(p.id,p);return `<tr><td><strong>${esc(p.name)}</strong><small>${esc(p.sku)} · ${esc(p.brand)}</small></td><td>${esc(p.category)}<small>${esc(p.subcategory||'Sin subcategoría')}</small></td><td>${money(p.retail)}</td><td>${money(p.wholesale)}</td><td>${p.stock}</td><td>${p.active?'Activo':'Inactivo'}</td><td><button class="btn outline small" data-edit="${p.id}">Editar</button>${p.active?`<button class="btn outline small" data-deactivate="${p.id}">Desactivar</button>`:''}</td></tr>`;}).join('')}</tbody></table></div><div class="pagination"><button data-admin-page="${adminPage-1}" ${adminPage===1?'disabled':''}>← Anterior</button><span>${data.total} artículos · Página ${adminPage}</span><button data-admin-page="${adminPage+1}" ${adminPage*30>=data.total?'disabled':''}>Siguiente →</button></div>`;}
if(adminTab==='imagenes')return imageLibraryMarkup(await api('/api/admin/images?page='+mediaPage),adminConfig.uploadLimitMb);
if(adminTab==='excel')return importHelpMarkup(adminConfig.uploadLimitMb);
if(adminTab==='solicitudes'){const rows=await api('/api/admin/requests');return rows.length?`<div class="table-scroll"><table class="data-table"><thead><tr><th>Comercio / Contacto</th><th>CUIT</th><th>Teléfono / Dirección</th><th>Estado</th><th>Acceso</th></tr></thead><tbody>${rows.map(r=>`<tr><td><strong>${esc(r.company)}</strong><small>${esc(r.name)} · ${esc(r.email)}</small></td><td>${esc(r.tax_id)}</td><td>${esc(r.phone)}<small>${esc(r.address)}</small></td><td><span class="pill">${({pending:'Pendiente',approved:'Aprobado',rejected:'Rechazado'})[r.wholesale_status]}</span></td><td>${r.wholesale_status!=='approved'?`<button class="btn small" data-request="${r.id}" data-status="approved">Aprobar</button>`:''}<button class="btn outline small" data-request="${r.id}" data-status="rejected">${r.wholesale_status==='approved'?'Revocar':'Rechazar'}</button></td></tr>`).join('')}</tbody></table></div>`:empty('Las próximas conexiones empiezan acá.','Todavía no recibiste solicitudes mayoristas.');}
if(adminTab==='pedidos'){const orders=await api('/api/admin/orders');return orders.length?orders.map(o=>`<article class="order-card"><div><strong>Pedido #${String(o.id).padStart(5,'0')} · ${esc(o.name)}</strong><strong>${money(o.total)}</strong></div><p>${esc(o.email)} · ${esc(o.phone)} · ${esc(o.address)}</p><p>${o.items.map(l=>`${l.qty} × ${esc(l.name)} (${money(l.unit)})`).join(' · ')}</p><p>${esc(o.note)}</p><div><span>${o.price_type} · ${new Date(o.created_at+'Z').toLocaleString('es-AR')}</span><select data-order-status="${o.id}" aria-label="Estado del pedido ${o.id}" ${o.status==='Cancelado'?'disabled':''}>${['Pendiente','Confirmado','En preparación','Despachado','Cancelado'].map(s=>`<option ${o.status===s?'selected':''}>${s}</option>`).join('')}</select></div></article>`).join(''):empty('Todo listo para recibir pedidos.','Los pedidos nuevos aparecerán acá.');}
const messages=await api('/api/admin/messages');return messages.length?messages.map(m=>`<article class="order-card"><div><strong>${esc(m.name)} · ${esc(m.email)}</strong><span>${new Date(m.created_at+'Z').toLocaleDateString('es-AR')}</span></div><p>${esc(m.message)}</p></article>`).join(''):empty('Tu bandeja de consultas está al día.','Los mensajes del formulario de contacto aparecerán acá.');}
function productEditor(p={}){const defaults={sku:'',name:'',brand:'',category:'Escolar',subcategory:'',description:'',retail:0,wholesale:0,stock:0,min_qty:1,image:'',featured:0,active:1,...p};$('#product-editor').innerHTML=`<div class="form-panel editor"><h2>${p.id?'Editar artículo':'Nuevo artículo'}</h2><form id="product-form" class="form-stack"><div class="editor-fields">${input('sku','SKU (identificador único)','text',defaults.sku,`required maxlength="80" ${p.id?'readonly':''}`)}${input('name','Nombre del artículo','text',defaults.name,'required maxlength="180"')}${input('brand','Marca','text',defaults.brand,'required maxlength="100"')}<div><label for="category">Categoría</label><select name="category" id="category">${categories.map(c=>`<option ${c===defaults.category?'selected':''}>${c}</option>`).join('')}</select></div>${input('subcategory','Subcategoría (por ejemplo: Bolígrafos)','text',defaults.subcategory,'maxlength="100"')}${input('retail','Precio minorista (ARS)','number',defaults.retail,'required min="0" step="0.01"')}${input('wholesale','Precio mayorista (ARS)','number',defaults.wholesale,'required min="0" step="0.01"')}${input('stock','Stock','number',defaults.stock,'required min="0" step="1"')}${input('min_qty','Mínimo mayorista','number',defaults.min_qty,'required min="1" step="1"')}<div><label for="active">Estado</label><select name="active" id="active"><option value="1" ${defaults.active?'selected':''}>Activo</option><option value="0" ${!defaults.active?'selected':''}>Inactivo</option></select></div><div class="wide"><label for="description">Descripción</label><textarea name="description" id="description" maxlength="3000">${esc(defaults.description)}</textarea></div><div class="wide">${input('image','URL de la imagen (HTTPS o archivo cargado)','text',defaults.image)}<button type="button" class="inline-link" data-copy-from="image">Copiar URL</button><p class="note">También podés subir fotos y copiar sus URL en la pestaña Imágenes.</p></div><div><label for="featured">Destacado en inicio</label><select name="featured" id="featured"><option value="0" ${!defaults.featured?'selected':''}>No</option><option value="1" ${defaults.featured?'selected':''}>Sí</option></select></div></div><div class="editor-photo"><img id="image-preview" src="${esc(defaults.image||'/assets/placeholder.svg')}" alt="Vista previa del producto"><div><label for="upload-image">O cargar una fotografía (JPG, PNG, WebP · hasta ${adminConfig.uploadLimitMb} MB)</label><input id="upload-image" type="file" accept="image/jpeg,image/png,image/webp"></div></div><p class="form-error" role="alert"></p><div><button class="btn" type="submit">Guardar artículo</button> <button class="btn outline" id="cancel-editor" type="button">Cancelar</button></div></form></div>`;$('#product-editor').scrollIntoView({behavior:'smooth',block:'start'});}
async function reloadAdmin(){const content=await adminContent();if($('#admin-content'))$('#admin-content').innerHTML=content;}
async function render(){carouselCleanup();const version=++renderVersion;$('#app').innerHTML='<div class="loading" role="status">Preparando tus próximas ideas…</div>';try{const route=location.pathname;let content;if(route==='/')content=await home();else if(route==='/catalogo')content=await catalog();else if(route==='/mayoristas')content=wholesalePage();else if(route==='/cuenta')content=await account();else if(route==='/contacto')content=contact();else if(route==='/nosotros')content=about();else if(route==='/ayuda')content=help();else if(route==='/checkout')content=await checkout();else if(route==='/admin')content=await admin();else if(route==='/privacidad'||route==='/terminos')content=legal(route.slice(1));else content=heading('Esta página se salió del cuaderno.')+`<div class="wrap form-page">${empty('Volvamos a las ideas.','No encontramos la página que buscás.','/','Ir al inicio')}</div>`;if(version!==renderVersion)return;$('#app').innerHTML=content;if(route==='/')initCarousel();else if(route==='/catalogo')initCarousel('.category-brand-carousel');$('#search-input').value=new URLSearchParams(location.search).get('q')||'';document.title=(({ '/':'Ideas que toman color','/catalogo':'Catálogo','/mayoristas':'Acceso mayorista','/cuenta':'Mi cuenta','/admin':'Administración','/checkout':'Tu pedido','/contacto':'Contacto','/nosotros':'Nosotros','/ayuda':'Ayuda'})[route]||'Acuarelas')+' · Acuarelas Distribuidora';}catch(e){if(version===renderVersion)$('#app').innerHTML=`<div class="error-page"><h2>No pudimos cargar esta página.</h2><p>${esc(e.message)}</p><button class="btn" id="retry">Volver a intentar</button></div>`;}}
document.addEventListener('click',async e=>{const link=e.target.closest('a[data-link]');if(link){if(e.metaKey||e.ctrlKey||e.shiftKey)return;e.preventDefault();navigate(link.getAttribute('href'));return;}const close=e.target.closest('[data-close]');if(close){$('#'+close.dataset.close).close();return;}const add=e.target.closest('[data-add]');if(add){await addProduct(Number(add.dataset.add));return;}const detail=e.target.closest('[data-product]');if(detail){await productDetail(Number(detail.dataset.product));return;}const remove=e.target.closest('[data-remove]');if(remove){cart=cart.filter(l=>l.id!==Number(remove.dataset.remove));saveCart();await drawCart();return;}const qty=e.target.closest('[data-qty]');if(qty){const l=cart.find(l=>l.id===Number(qty.dataset.qty));if(!l)return;const p=l.product;const next=l.qty+Number(qty.dataset.delta);if(next> (p?.stock||0))return toast('No hay stock suficiente.');if(next<=0){cart=cart.filter(x=>x!==l);}else{if(user?.wholesale_status==='approved'&&next<p.min_qty)return toast(`El mínimo mayorista es de ${p.min_qty} unidades. Podés eliminar el artículo.`);l.qty=next;}saveCart();await drawCart();return;}const chip=e.target.closest('[data-home-category]');if(chip){try{const category=chip.dataset.homeCategory;const data=await api('/api/products?limit=8'+(category==='Todos'?'&featured=1':'&category='+category));if(!$('#home-products'))return;$('#home-products').innerHTML=data.items.map(productCard).join('');document.querySelectorAll('[data-home-category]').forEach(b=>b.classList.toggle('active',b===chip));}catch(err){toast(err.message);}return;}const page=e.target.closest('[data-page]');if(page){changeFilter('page',page.dataset.page,false);return;}const authTab=e.target.closest('[data-auth-tab]');if(authTab){const register=authTab.dataset.authTab==='register';$('#auth-form').dataset.mode=register?'register':'login';$('#register-name').classList.toggle('hidden',!register);$('#name').required=register;$('#password').setAttribute('autocomplete',register?'new-password':'current-password');$('#password').minLength=register?10:1;$('#auth-submit').textContent=register?'Crear mi cuenta':'Ingresar';document.querySelectorAll('[data-auth-tab]').forEach(b=>b.classList.toggle('active',b===authTab));return;}const tab=e.target.closest('[data-admin-tab]');if(tab){adminTab=tab.dataset.adminTab;try{await render();}catch(err){toast(err.message);}return;}const edit=e.target.closest('[data-edit]');if(edit){productEditor(currentProducts.get(Number(edit.dataset.edit)));return;}const deactivate=e.target.closest('[data-deactivate]');if(deactivate){const p=currentProducts.get(Number(deactivate.dataset.deactivate));if(!confirm(`¿Desactivar “${p.name}”? Dejará de aparecer en el catálogo. Podés reactivarlo al editarlo.`))return;try{await api('/api/admin/products/'+deactivate.dataset.deactivate,{method:'DELETE'});toast('Artículo desactivado');await reloadAdmin();}catch(err){toast(err.message);}return;}const request=e.target.closest('[data-request]');if(request){if(request.dataset.status==='rejected'&&!confirm('¿Rechazar o revocar el acceso mayorista de esta cuenta?'))return;try{await post('/api/admin/requests/'+request.dataset.request,{status:request.dataset.status},'PATCH');toast('Acceso actualizado');await render();}catch(err){toast(err.message);}return;}const adminPager=e.target.closest('[data-admin-page]');if(adminPager){adminPage=Number(adminPager.dataset.adminPage);await reloadAdmin();return;}if(e.target.closest('#new-product'))productEditor();if(e.target.closest('#cancel-editor'))$('#product-editor').innerHTML='';if(e.target.closest('#retry'))render();if(e.target.closest('#logout')){await post('/api/logout',{});await refreshUser();render();toast('Sesión cerrada');}if(e.target.closest('#confirm-import')){const btn=e.target.closest('#confirm-import');btn.disabled=true;try{const result=await post('/api/admin/import/confirm',{token:btn.dataset.token});toast(`${result.count} artículos guardados`);$('#import-result').innerHTML='<div class="status-banner">La importación se completó correctamente.</div>';}catch(err){toast(err.message);btn.disabled=false;}}});
function changeFilter(key,value,reset=true){const params=new URLSearchParams(location.search);value?params.set(key,value):params.delete(key);if(reset)params.delete('page');navigate('/catalogo?'+params);}
document.addEventListener('change',async e=>{if(e.target.id==='subcategory-filter')changeFilter('subcategory',e.target.value);if(e.target.id==='brand-filter')changeFilter('brand',e.target.value);if(e.target.id==='sort-filter')changeFilter('sort',e.target.value);if(e.target.id==='stock-filter')changeFilter('stock',e.target.checked?'1':'');if(e.target.dataset.orderStatus){if(e.target.value==='Cancelado'&&!confirm('¿Cancelar este pedido y devolver las unidades al stock?')){await reloadAdmin();return;}try{await post('/api/admin/orders/'+e.target.dataset.orderStatus,{status:e.target.value},'PATCH');toast('Estado del pedido actualizado');await reloadAdmin();}catch(err){toast(err.message);}}if(e.target.id==='upload-image'){const file=e.target.files[0];if(!file)return;if(file.size>adminConfig.uploadLimitMb*1024*1024)return toast(`La imagen supera ${adminConfig.uploadLimitMb} MB. Comprimila antes de subirla.`);const body=new FormData();body.append('image',file);try{const result=await api('/api/admin/image',{method:'POST',body});$('#image').value=result.url;$('#image-preview').src=result.url;toast('Imagen cargada. Guardá el artículo para asociarla.');}catch(err){toast(err.message);}}});
document.addEventListener('input',e=>{if(e.target.id==='admin-search'){clearTimeout(searchTimer);searchTimer=setTimeout(async()=>{adminQ=e.target.value;adminPage=1;const start=e.target.selectionStart;await reloadAdmin();$('#admin-search')?.focus();$('#admin-search')?.setSelectionRange(start,start);},400);}});
document.addEventListener('submit',async e=>{const f=e.target;if(f.id==='search-form'){e.preventDefault();const q=$('#search-input').value.trim();navigate('/catalogo'+(q?'?q='+encodeURIComponent(q):''));return;}if(!['auth-form','wholesale-form','contact-form','checkout-form','product-form','import-form','password-form'].includes(f.id))return;e.preventDefault();const button=f.querySelector('button[type="submit"]');const error=f.querySelector('.form-error');error.textContent='';button.disabled=true;const data=Object.fromEntries(new FormData(f));try{
if(f.id==='auth-form'){if(f.dataset.mode==='register')await post('/api/register',data);await post('/api/login',{email:data.email,password:data.password});await refreshUser();if(location.pathname==='/admin'&&user.role!=='admin')navigate('/cuenta');else await render();toast('¡Bienvenido a Acuarelas!');}
if(f.id==='wholesale-form'){await post('/api/wholesale',data);await refreshUser();await render();toast('Recibimos tu solicitud mayorista');}
if(f.id==='contact-form'){await post('/api/contact',data);f.reset();toast('Tu consulta fue recibida. Nuestro equipo la revisará.');}
if(f.id==='password-form'){await post('/api/password',data);f.reset();toast('Contraseña actualizada');}
if(f.id==='checkout-form'){const order=await post('/api/orders',{...data,items:cart.map(({id,qty})=>({id,qty}))});cart=[];saveCart();$('#app').innerHTML=`<div class="wrap success-page"><div class="success-mark">✓</div><div class="eyebrow">Una nueva idea en camino</div><h1>¡Recibimos tu pedido!</h1><p>Pedido <strong>#${String(order.id).padStart(5,'0')}</strong> · Total ${money(order.total)}<br>Nuestro equipo te contactará para confirmar el pago y la entrega.</p><a href="/catalogo" data-link class="btn">Seguir explorando ↗</a></div>`;}
if(f.id==='product-form'){await post('/api/admin/products',data);toast('Artículo guardado');await reloadAdmin();}
if(f.id==='import-form'){const file=f.querySelector('input[type=file]').files[0];if(file?.size>adminConfig.uploadLimitMb*1024*1024)throw new Error(`La planilla supera ${adminConfig.uploadLimitMb} MB. Dividila en lotes más pequeños.`);const result=await api('/api/admin/import/preview',{method:'POST',body:new FormData(f)});$('#import-result').innerHTML=importResultMarkup(result);}
}catch(err){error.textContent=err.message;}finally{button.disabled=false;}});
$('#open-cart').addEventListener('click',async()=>{$('#cart-dialog').showModal();$('#cart-content').innerHTML='<div class="loading">Actualizando tu selección…</div>';try{await drawCart();}catch(e){toast(e.message);}});
document.addEventListener('error',e=>{if(e.target instanceof HTMLImageElement&&!e.target.src.endsWith('/assets/placeholder.svg')){e.target.src='/assets/placeholder.svg';e.target.classList.add('image-fallback');}},true);
window.addEventListener('popstate',render);
document.querySelectorAll('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close();}}));
document.addEventListener('click',async event=>{
  const copy=event.target.closest('[data-copy-image],[data-copy-from]');
  if(copy){
    const value=copy.dataset.copyImage||$('#'+copy.dataset.copyFrom)?.value;
    if(!value)return toast('Primero cargá una imagen o pegá su URL.');
    try{await navigator.clipboard.writeText(value);toast('URL copiada. Pegala en Imagen URL del Excel.');}
    catch{const field=copy.closest('.media-card')?.querySelector('input')||$('#'+copy.dataset.copyFrom);field?.focus();field?.select();toast('Seleccionamos la URL. Copiala con Ctrl+C.');}
    return;
  }
  const pager=event.target.closest('[data-media-page]');
  if(pager){mediaPage=Number(pager.dataset.mediaPage);try{await reloadAdmin();}catch(error){toast(error.message);}}
});
document.addEventListener('change',async event=>{
  if(event.target.id!=='library-upload')return;
  const input=event.target,files=Array.from(input.files||[]);
  if(!files.length)return;
  input.disabled=true;let uploaded=0;const errors=[];
  for(let i=0;i<files.length;i++){
    const file=files[i];
    if($('#image-upload-status'))$('#image-upload-status').textContent=`Subiendo ${i+1} de ${files.length}: ${file.name}`;
    if(file.size>adminConfig.uploadLimitMb*1024*1024){errors.push(`${file.name}: supera ${adminConfig.uploadLimitMb} MB.`);continue;}
    const body=new FormData();body.append('image',file);
    try{await api('/api/admin/image',{method:'POST',body});uploaded++;}
    catch(error){errors.push(`${file.name}: ${error.message}`);}
  }
  mediaPage=1;
  if(adminTab==='imagenes'&&location.pathname==='/admin'){
    try{await reloadAdmin();const status=$('#image-upload-status');if(status)status.innerHTML=`<p>${uploaded} imágenes subidas. Ya podés copiar sus URL.</p>${errors.length?`<ul class="form-error">${errors.map(error=>`<li>${esc(error)}</li>`).join('')}</ul>`:''}`;}
    catch(error){toast(error.message);input.disabled=false;}
  }
});
$('#year').textContent=new Date().getFullYear();updateCount();refreshUser().then(render).catch(()=>render());
